/* ===================== BÀI 1 · Dữ liệu, cơ sở dữ liệu và hệ quản trị cơ sở dữ liệu ===================== */
/* Bài 1 · Dữ liệu, cơ sở dữ liệu và hệ quản trị cơ sở dữ liệu (AMTS-DAT-001-M01-L01, SQL-C01-L01) — sinh bởi tools/author/sql/l01.js, không sửa tay.
   Trình soạn SQL (57-sql-*.js, SQLite chỉ tải khi trình soạn hiện lên hoặc khi bấm nút) và bài tập không viết code (makeMtEx, courses/sql/course.js). */
makeSqlLab(document.getElementById("sql-l1"),{id:"sql-l1",file:"bai-1.sql",presets:[{"label":"Ví dụ: xem cả bảng hoc_vien","note":"Câu lệnh đơn giản nhất: SELECT * nghĩa là mọi cột. DBMS đọc bảng và trả về 8 dòng. Bật Đoán trước để đoán số dòng trước khi chạy.","data":"lop","sql":"-- Hỏi DBMS: cho xem mọi cột, mọi dòng của bảng hoc_vien\nSELECT * FROM hoc_vien;"},{"label":"Ví dụ: từ dữ liệu ra thông tin","note":"8 dòng là dữ liệu; ba con số trong Kết quả là thông tin: 8 học viên, 7 người có điểm, điểm trung bình 7.57 của 7 người đó. COUNT, AVG học kỹ ở Chương 4.","data":"lop","sql":"-- Từ 8 dòng dữ liệu rút ra ba con số (thông tin)\nSELECT COUNT(*) AS so_hoc_vien,\n       COUNT(diem) AS so_co_diem,\n       ROUND(AVG(diem), 2) AS diem_tb\nFROM hoc_vien;"},{"label":"Ví dụ: chỉ hỏi điều cần biết","note":"Câu lệnh chỉ nói muốn gì (họ tên và điểm của lớp 10A), không nói cách tìm. DBMS tự đọc bảng và chọn 3 dòng. Câu không có ORDER BY nên thứ tự dòng không được hứa trước.","data":"lop","sql":"-- Nói điều cần lấy; DBMS tự tìm các dòng phù hợp\nSELECT ho_ten, diem\nFROM hoc_vien\nWHERE lop = '10A';"},{"label":"Ví dụ: DBMS ghi lại thay đổi","note":"Bấm Từng bước. Câu UPDATE đổi đúng 1 dòng (phần Cơ sở dữ liệu đánh dấu bảng vừa đổi); câu SELECT sau đó đọc được điểm mới. Bấm ↺ để trở về dữ liệu mẫu.","data":"lop","sql":"-- Phạm Dũng (id 4) thi bù được 7 điểm: DBMS ghi lại\nUPDATE hoc_vien SET diem = 7 WHERE id = 4;\n\n-- Đọc lại để thấy thay đổi đã được ghi\nSELECT id, ho_ten, diem FROM hoc_vien WHERE id = 4;"},{"label":"Ví dụ: hỏi DBMS là phiên bản nào","note":"Phòng thực hành chạy SQLite, nên kết quả là số phiên bản SQLite. Hàm sqlite_version() chỉ SQLite có; trên PostgreSQL câu này báo lỗi, phải viết SELECT version();.","data":"lop","sql":"-- Mỗi DBMS có hàm riêng cho biết phiên bản của nó\n-- SQLite: sqlite_version()   PostgreSQL: version()\nSELECT sqlite_version() AS phien_ban;"},{"label":"Lỗi: DBMS chặn điểm 12","note":"Bảng được tạo với quy tắc điểm từ 0 đến 10. DBMS từ chối câu UPDATE, báo lỗi và không đổi dòng nào; câu SELECT sau đó vẫn đọc được điểm cũ 6.","data":"lop","sql":"-- Cột diem có quy tắc CHECK (diem BETWEEN 0 AND 10)\nUPDATE hoc_vien SET diem = 12 WHERE id = 2;\n\n-- Dữ liệu cũ vẫn còn nguyên\nSELECT id, ho_ten, diem FROM hoc_vien WHERE id = 2;"},{"label":"Lỗi: nhập trùng mã học viên","note":"Mã id 3 đã là của Lê Chi. Nhập lại lần nữa bị chặn vì id là khóa chính (PRIMARY KEY); bảng vẫn có 8 dòng, không có bản ghi lặp.","data":"lop","sql":"-- id là khóa chính: không được có hai dòng cùng id\nINSERT INTO hoc_vien (id, ho_ten, lop, nam_sinh, diem)\nVALUES (3, 'Lê Chi', '10B', 2010, 9);\n\n-- Bảng vẫn có 8 dòng\nSELECT COUNT(*) AS so_dong FROM hoc_vien;"},{"label":"Bẫy: hai “điểm trung bình” của 10B","note":"Cùng dữ liệu, hai con số: AVG(diem) bỏ qua người vắng thi nên ra 8.5; chia tổng điểm cho cả 3 người ra 5.67. Thông tin chỉ đúng khi ghi rõ con số đó tính trên những ai.","data":"lop","sql":"-- Lớp 10B: Lê Chi 9, Phạm Dũng vắng thi (NULL), Bùi Khánh 8\n-- Hai cách tính \"điểm trung bình\", hai con số khác nhau\nSELECT ROUND(AVG(diem), 2) AS tb_nguoi_co_diem,\n       ROUND(SUM(diem) * 1.0 / COUNT(*), 2) AS tb_ca_lop\nFROM hoc_vien\nWHERE lop = '10B';"},{"label":"Lỗi: gõ sai tên bảng","note":"DBMS không đoán ý: không có bảng tên hocvien thì báo lỗi, không trả về dòng nào. Xem tên bảng đúng trong phần Cơ sở dữ liệu.","data":"lop","sql":"-- Tên bảng đúng là hoc_vien (có dấu gạch dưới)\nSELECT * FROM hocvien;"}]});
makeMtEx(document.getElementById("ex-l1"),"l1",[{"t":"Gọi đúng tên","kind":"pick","d":"<p>Mỗi mục dưới đây là một <b>dữ liệu<\/b>, một <b>thông tin<\/b>, một <b>cơ sở dữ liệu<\/b>, một <b>hệ quản trị cơ sở dữ liệu<\/b> hay một <b>ứng dụng<\/b>? Chọn một loại cho mỗi mục.<\/p>","hints":["Dữ liệu là giá trị ghi lại một sự việc; thông tin là câu trả lời rút ra từ nhiều giá trị.","Cơ sở dữ liệu là chính dữ liệu đã được tổ chức (thường nằm trong file hoặc thư mục); hệ quản trị CSDL là phần mềm đọc, ghi và bảo vệ dữ liệu đó.","Ứng dụng là chương trình người dùng cuối nhìn thấy; nó không tự lưu dữ liệu mà gửi yêu cầu cho hệ quản trị CSDL."],"why":"Giá trị 8 là dữ liệu; câu tóm tắt về lớp 10A là thông tin. File truong.db là cơ sở dữ liệu. PostgreSQL và SQLite là hệ quản trị CSDL: chúng chạy câu lệnh và chặn dữ liệu sai. Trang web tra cứu là ứng dụng, đứng trước hệ quản trị CSDL.","cats":["Dữ liệu","Thông tin","Cơ sở dữ liệu","Hệ quản trị CSDL","Ứng dụng"],"items":[{"q":"Giá trị 8 ở cột diem của dòng Nguyễn An.","a":0},{"q":"Câu “Lớp 10A có 3 học viên, điểm trung bình 8.0”, rút ra từ bảng hoc_vien.","a":1},{"q":"File truong.db chứa bảng hoc_vien, bảng lop_hoc và mô tả các cột của hai bảng.","a":2},{"q":"Phần mềm PostgreSQL nhận câu SELECT, tìm các dòng phù hợp và gửi kết quả về.","a":3},{"q":"Trang web tra cứu điểm cho phụ huynh, gửi câu truy vấn tới PostgreSQL rồi hiện kết quả.","a":4},{"q":"Phần mềm SQLite từ chối câu UPDATE ghi điểm 12 vào cột diem.","a":3}]},{"t":"Hệ quản trị CSDL đang làm việc gì?","kind":"pick","d":"<p>Mỗi tình huống ở một trường học (giả định) cho thấy hệ quản trị cơ sở dữ liệu làm một việc thay người dùng. Chọn đúng việc đó.<\/p>","hints":["Đọc động từ chính của tình huống: còn nguyên sau khi tắt máy, bị từ chối, cùng lúc, chỉ được đọc, dựng lại, hỏi và nhận lại.","Bị từ chối vì vi phạm quy tắc của bảng (trùng khóa chính, điểm ngoài 0…10) là việc giữ dữ liệu đúng, không phải phân quyền.","Phân quyền là chuyện ai được làm gì (đọc, sửa); sao lưu và phục hồi là chuyện dựng lại dữ liệu sau sự cố."],"why":"Lưu bền: dữ liệu còn sau khi tắt máy. Ràng buộc (khóa chính) giữ dữ liệu đúng. Điều khiển truy cập đồng thời cho nhiều người cùng ghi. Phân quyền: tài khoản phụ huynh chỉ đọc. Sao lưu và phục hồi sau sự cố ổ đĩa. Truy vấn: hỏi và nhận lại các dòng phù hợp (lớp 10A có Nguyễn An 8 và Hoàng Em 10).","cats":["Lưu trữ bền","Truy vấn","Giữ dữ liệu đúng quy tắc","Cho nhiều người dùng cùng lúc","Phân quyền","Sao lưu và phục hồi"],"items":[{"q":"Tắt máy chủ qua đêm, sáng hôm sau bảng hoc_vien vẫn đủ 8 dòng như cũ.","a":0},{"q":"Câu INSERT thứ hai với id = 3 bị từ chối vì id 3 đã là của một học viên khác.","a":2},{"q":"Hai giáo viên cùng lúc nhập điểm cho hai lớp khác nhau; điểm của người này không ghi đè điểm của người kia.","a":3},{"q":"Tài khoản của phụ huynh chỉ được đọc điểm, không được sửa điểm.","a":4},{"q":"Ổ đĩa máy chủ hỏng; nhà trường dùng bản sao lưu đêm trước để dựng lại dữ liệu.","a":5},{"q":"Giáo viên hỏi danh sách học viên lớp 10A có điểm từ 8 trở lên và nhận lại 2 dòng.","a":1}]},{"t":"Đọc kết quả từ phòng thực hành","kind":"num","d":"<p>Dùng trình soạn SQL ở mục 1.5 (dữ liệu mẫu Lớp học, bảng <code>hoc_vien<\/code>). Chọn ví dụ phù hợp, chạy rồi đọc phần <b>Kết quả<\/b>; có thể tự sửa câu lệnh. Bấm ↺ để trở về dữ liệu mẫu trước mỗi câu. Số thập phân dùng dấu chấm hoặc dấu phẩy, làm tròn 2 chữ số.<\/p>","hints":["Ví dụ “xem cả bảng” và “từ dữ liệu ra thông tin” trả lời ngay hai câu đầu. COUNT(*) đếm dòng, COUNT(diem) chỉ đếm ô có giá trị.","Ví dụ “Bẫy: hai điểm trung bình của 10B” cho cả hai con số của câu 3 và câu 4. Lớp 10B có 3 học viên, một người vắng thi.","Câu UPDATE ghi điểm 12 vi phạm quy tắc 0…10 của cột diem nên bị từ chối; dòng id 2 giữ nguyên giá trị cũ (xem ví dụ “Lỗi: DBMS chặn điểm 12”)."],"why":"8 dòng, 7 người có điểm. Lớp 10B: (9 + 8) / 2 = 8.5 nếu chỉ tính người có điểm, (9 + 8) / 3 ≈ 5.67 nếu chia cho cả lớp: cùng dữ liệu nhưng hai thông tin khác nhau, phải ghi rõ cách tính. Câu UPDATE điểm 12 bị DBMS chặn nên điểm của Trần Bình vẫn là 6.","items":[{"q":"Bảng hoc_vien có bao nhiêu dòng?","a":8,"unit":"dòng"},{"q":"Bao nhiêu học viên đã có điểm (ô diem khác NULL)?","a":7,"unit":"học viên"},{"q":"Điểm trung bình của lớp 10B theo AVG(diem), chỉ tính người có điểm?","a":8.5,"tol":0.005},{"q":"Tổng điểm của lớp 10B chia cho số học viên của lớp (kể cả người vắng thi)?","a":5.67,"tol":0.005},{"q":"Chạy UPDATE hoc_vien SET diem = 12 WHERE id = 2; rồi đọc lại. Điểm của Trần Bình (id 2) bây giờ là bao nhiêu?","a":6,"unit":"điểm"}]}]);

makeQuiz("quiz1","score1",[{"q": "Lớp 10B có Lê Chi 9 điểm, Phạm Dũng vắng thi (diem là NULL), Bùi Khánh 8 điểm. Câu SELECT COUNT(*), COUNT(diem) FROM hoc_vien WHERE lop = '10B'; cho kết quả nào?", "o": ["3 và 3", "2 và 2", "3 và 2", "2 và 3"], "a": 2, "e": "COUNT(*) đếm số dòng (3 học viên); COUNT(diem) chỉ đếm ô diem có giá trị (2). Chọn “3 và 3” là quên rằng ô NULL không được đếm."}, {"q": "Cột diem có quy tắc CHECK (diem BETWEEN 0 AND 10); Trần Bình (id 2) đang có 6 điểm. Chạy UPDATE hoc_vien SET diem = 12 WHERE id = 2; rồi SELECT diem FROM hoc_vien WHERE id = 2;. Câu SELECT cho kết quả nào?", "o": ["6, vì câu UPDATE bị từ chối", "12, vì câu UPDATE vẫn được ghi", "10, vì DBMS tự hạ về mức cao nhất", "NULL, vì DBMS xóa ô bị lỗi"], "a": 0, "e": "DBMS kiểm tra quy tắc trước khi ghi; vi phạm thì từ chối cả câu lệnh và giữ nguyên dữ liệu cũ. DBMS không tự sửa giá trị thành 10 hay NULL."}, {"q": "Câu nào là thông tin rút ra từ dữ liệu, chứ không chỉ là một giá trị dữ liệu?", "o": ["Ô diem của dòng id 1 chứa giá trị 8", "Ô lop của dòng id 6 đang để trống (NULL)", "Cột ho_ten có kiểu TEXT và không được trống", "Lớp 10A có 3 học viên, điểm trung bình 8.0"], "a": 3, "e": "Câu về lớp 10A trả lời một câu hỏi bằng cách xử lý nhiều dòng (đếm, tính trung bình). Câu về ô diem của dòng id 1 và câu về ô lop của dòng id 6 chỉ đọc một ô; câu về cột ho_ten mô tả cấu trúc bảng (siêu dữ liệu)."}, {"q": "Điểm khác nhau chính giữa SQLite và PostgreSQL về cách chạy là gì?", "o": ["SQLite không dùng ngôn ngữ SQL; PostgreSQL dùng SQL làm ngôn ngữ chính để làm việc", "SQLite chạy ngay trong chương trình, CSDL là một file; PostgreSQL là máy chủ riêng, chương trình khác kết nối tới", "SQLite chỉ chạy được trên điện thoại; PostgreSQL chỉ chạy được trên máy tính Windows", "SQLite lưu dữ liệu trên máy chủ mạng; PostgreSQL chỉ giữ dữ liệu trong bộ nhớ RAM"], "a": 1, "e": "SQLite là thư viện nhúng, không có tiến trình máy chủ, cả CSDL nằm trong một file. PostgreSQL chạy một tiến trình máy chủ; psql, pgAdmin hay ứng dụng là chương trình khách kết nối tới. Cả hai đều dùng SQL và chạy trên nhiều hệ điều hành."}, {"q": "Bảng thật tên là hoc_vien. Chạy SELECT * FROM hocvien; thì điều gì xảy ra?", "o": ["Không báo lỗi, trả về 0 dòng", "DBMS tự hiểu là hoc_vien và trả về 8 dòng", "Báo lỗi no such table: hocvien, không có dòng nào", "DBMS tạo bảng mới hocvien rỗng rồi trả về"], "a": 2, "e": "DBMS làm đúng từng chữ của câu lệnh, không đoán ý. Bảng không tồn tại là lỗi (SQLite: no such table; PostgreSQL: relation \"hocvien\" does not exist), khác với bảng có thật nhưng không có dòng nào phù hợp (0 dòng)."}]);

